import React, { useEffect, useState } from "react";

import Login from "./components/Login";
import Register from "./components/Register";
import Header from "./components/Header";
import Sidebar from "./components/Sidebar";
import DisputeForm from "./components/DisputeForm";

import "./App.css";


function App() {

    const [student, setStudent] =
        useState(null);

    const [showRegister, setShowRegister] =
        useState(false);

    const [disputes, setDisputes] =
        useState([]);


    // Check existing login
    useEffect(() => {

        const savedStudent =
            localStorage.getItem(
                "student"
            );

        if (savedStudent) {

            setStudent(
                JSON.parse(savedStudent)
            );
        }

    }, []);


    // Load disputes
    useEffect(() => {

        if (!student) {
            return;
        }

        loadDisputes();

    }, [student]);


    const loadDisputes = async () => {

        try {

            const response = await fetch(
                `http://localhost:5000/api/disputes/${student.student_id}`
            );

            const data =
                await response.json();

            setDisputes(data);

        } catch (error) {

            console.error(
                "Error loading disputes:",
                error
            );

        }
    };


    // Login
    const handleLogin = (studentData) => {

        setStudent(studentData);

        localStorage.setItem(
            "student",
            JSON.stringify(studentData)
        );

        setShowRegister(false);
    };




    // Logout
    const handleLogout = () => {

        localStorage.removeItem(
            "student"
        );

        setStudent(null);
        setDisputes([]);
    };


    // Create dispute
    const handleCreateDispute = async (
        disputeData
    ) => {

        const response = await fetch(
            "http://localhost:5000/api/disputes",
            {
                method: "POST",

                headers: {
                    "Content-Type":
                        "application/json"
                },

                body: JSON.stringify({
                    student_id:
                        student.student_id,

                    subject:
                        disputeData.subject,

                    grade_date:
                        disputeData.grade_date,

                    reason:
                        disputeData.reason
                })
            }
        );


        const data =
            await response.json();


        if (!response.ok) {

            alert(data.message);

            throw new Error(
                data.message
            );
        }


        await loadDisputes();

        alert(
            "Dispute submitted successfully!"
        );
    };


    // If not logged in
    if (!student) {

        if (showRegister) {

            return (
                <Register
                    onBackToLogin={() =>
                        setShowRegister(false)
                    }
                />
            );

        }


        return (
            <Login
                onLogin={handleLogin}
                onRegister={() =>
                    setShowRegister(true)
                }
            />
        );
    }


    // Dashboard
    return (

        <div className="app">

            <Header
                student={student}
                onLogout={handleLogout}
            />

            <div className="dashboard-layout">

                <Sidebar
                    disputes={disputes}
                />

                <main className="main-content">

                    <DisputeForm
                        onCreated={
                            handleCreateDispute
                        }
                    />

                </main>

            </div>

        </div>
    );
}

export default App;
